use std::collections::{BTreeMap, HashMap};

use erd_proto::AudioFragment;

const MAX_PENDING_AUDIO_FRAMES: usize = 64;

#[derive(Debug)]
struct PendingAudioFrame {
    fragment_count: u16,
    fragments: BTreeMap<u16, Vec<u8>>,
}

/// Reassembles audio fragments and discards incomplete older frames once newer audio arrives.
#[derive(Debug, Default)]
pub struct AudioFragmentReassembler {
    pending: HashMap<u32, PendingAudioFrame>,
    newest_frame_id: Option<u32>,
    skipped_frames: u64,
}

impl AudioFragmentReassembler {
    pub fn push(&mut self, fragment: AudioFragment) -> Option<Vec<u8>> {
        let frame_id = fragment.header.frame_id;
        if self.newest_frame_id.is_some_and(|newest| frame_id < newest) {
            return None;
        }

        if self.newest_frame_id.map_or(true, |newest| frame_id > newest) {
            self.skip_incomplete_before(frame_id);
            self.newest_frame_id = Some(frame_id);
        }

        if fragment.header.fragment_count == 1 {
            self.pending.remove(&frame_id);
            return Some(fragment.data);
        }

        let entry = self
            .pending
            .entry(frame_id)
            .or_insert_with(|| PendingAudioFrame {
                fragment_count: fragment.header.fragment_count,
                fragments: BTreeMap::new(),
            });
        if entry.fragment_count != fragment.header.fragment_count {
            self.pending.remove(&frame_id);
            self.skipped_frames += 1;
            return None;
        }
        entry
            .fragments
            .entry(fragment.header.fragment_index)
            .or_insert(fragment.data);

        if entry.fragments.len() == entry.fragment_count as usize {
            let entry = self.pending.remove(&frame_id)?;
            let total_bytes = entry.fragments.values().map(Vec::len).sum();
            let mut assembled = Vec::with_capacity(total_bytes);
            for index in 0..entry.fragment_count {
                assembled.extend_from_slice(entry.fragments.get(&index)?);
            }
            return Some(assembled);
        }

        if self.pending.len() > MAX_PENDING_AUDIO_FRAMES {
            let oldest = self.pending.keys().copied().min()?;
            self.pending.remove(&oldest);
            self.skipped_frames += 1;
        }
        None
    }

    pub fn pending_frames(&self) -> usize {
        self.pending.len()
    }

    pub fn skipped_frames(&self) -> u64 {
        self.skipped_frames
    }

    pub fn clear(&mut self) {
        self.pending.clear();
        self.newest_frame_id = None;
    }

    fn skip_incomplete_before(&mut self, frame_id: u32) {
        let before = self.pending.len();
        self.pending.retain(|id, _| *id >= frame_id);
        self.skipped_frames += (before - self.pending.len()) as u64;
    }
}

use std::{
    collections::VecDeque,
    sync::{Arc, Mutex},
};

use cpal::{
    traits::{DeviceTrait, HostTrait, StreamTrait},
    BufferSize, SampleFormat, SampleRate, Stream, StreamConfig,
};
use thiserror::Error;

pub const AUDIO_SAMPLE_RATE: u32 = 48_000;
pub const AUDIO_CHANNELS: u16 = 2;

#[derive(Debug, Clone)]
pub struct AudioQueue {
    samples: Arc<Mutex<VecDeque<f32>>>,
    volume: Arc<Mutex<f32>>,
    muted: Arc<Mutex<bool>>,
}

impl Default for AudioQueue {
    fn default() -> Self {
        Self {
            samples: Arc::new(Mutex::new(VecDeque::new())),
            volume: Arc::new(Mutex::new(1.0)),
            muted: Arc::new(Mutex::new(false)),
        }
    }
}

impl AudioQueue {
    pub fn push_pcm_bytes(&self, bytes: &[u8]) -> Result<(), AudioError> {
        if bytes.len() % std::mem::size_of::<f32>() != 0 {
            return Err(AudioError::MisalignedPcm(bytes.len()));
        }
        let mut queue = self.samples.lock().map_err(|_| AudioError::Poisoned)?;
        queue.reserve(bytes.len() / 4);
        for sample in bytes.chunks_exact(4) {
            queue.push_back(f32::from_le_bytes(
                sample.try_into().expect("four-byte chunk"),
            ));
        }
        Ok(())
    }

    pub fn push_samples(&self, samples: impl IntoIterator<Item = f32>) -> Result<(), AudioError> {
        self.samples
            .lock()
            .map_err(|_| AudioError::Poisoned)?
            .extend(samples);
        Ok(())
    }

    pub fn queued_samples(&self) -> Result<usize, AudioError> {
        Ok(self.samples.lock().map_err(|_| AudioError::Poisoned)?.len())
    }

    pub fn set_volume(&self, volume: f32) -> Result<(), AudioError> {
        *self.volume.lock().map_err(|_| AudioError::Poisoned)? = volume.clamp(0.0, 1.0);
        Ok(())
    }

    pub fn set_muted(&self, muted: bool) -> Result<(), AudioError> {
        *self.muted.lock().map_err(|_| AudioError::Poisoned)? = muted;
        Ok(())
    }

    pub fn drain_into(&self, output: &mut [f32]) -> Result<usize, AudioError> {
        let muted = *self.muted.lock().map_err(|_| AudioError::Poisoned)?;
        let volume = *self.volume.lock().map_err(|_| AudioError::Poisoned)?;
        let mut samples = self.samples.lock().map_err(|_| AudioError::Poisoned)?;
        let mut consumed = 0;
        for destination in output {
            if let Some(sample) = samples.pop_front() {
                *destination = if muted { 0.0 } else { sample * volume };
                consumed += 1;
            } else {
                *destination = 0.0;
            }
        }
        Ok(consumed)
    }
}

#[derive(Debug, Error)]
pub enum AudioError {
    #[error("no default audio output device")]
    NoOutputDevice,
    #[error("default output uses {0:?}, but the v3 audio path requires f32")]
    UnsupportedSampleFormat(SampleFormat),
    #[error("PCM byte count {0} is not aligned to f32 samples")]
    MisalignedPcm(usize),
    #[error("audio queue lock was poisoned")]
    Poisoned,
    #[error("audio device error: {0}")]
    Device(String),
}

/// Active CPAL 48 kHz stereo f32 output stream backed by [`AudioQueue`].
pub struct CpalAudioOutput {
    queue: AudioQueue,
    stream: Stream,
}

impl CpalAudioOutput {
    pub fn start(queue: AudioQueue) -> Result<Self, AudioError> {
        let host = cpal::default_host();
        let device = host
            .default_output_device()
            .ok_or(AudioError::NoOutputDevice)?;
        let supported = device
            .supported_output_configs()
            .map_err(|error| AudioError::Device(error.to_string()))?
            .find(|config| {
                config.channels() == AUDIO_CHANNELS
                    && config.sample_format() == SampleFormat::F32
                    && config.min_sample_rate().0 <= AUDIO_SAMPLE_RATE
                    && config.max_sample_rate().0 >= AUDIO_SAMPLE_RATE
            })
            .ok_or(AudioError::UnsupportedSampleFormat(
                device
                    .default_output_config()
                    .map_err(|error| AudioError::Device(error.to_string()))?
                    .sample_format(),
            ))?;
        let config = StreamConfig {
            channels: AUDIO_CHANNELS,
            sample_rate: SampleRate(AUDIO_SAMPLE_RATE),
            buffer_size: BufferSize::Default,
        };
        let callback_queue = queue.clone();
        let stream = device
            .build_output_stream(
                &config,
                move |output: &mut [f32], _| {
                    let _ = callback_queue.drain_into(output);
                },
                |error| tracing::error!(%error, "CPAL output stream failed"),
                None,
            )
            .map_err(|error| AudioError::Device(error.to_string()))?;
        let _ = supported;
        stream
            .play()
            .map_err(|error| AudioError::Device(error.to_string()))?;
        Ok(Self { queue, stream })
    }

    pub fn queue(&self) -> &AudioQueue {
        &self.queue
    }

    pub fn stream(&self) -> &Stream {
        &self.stream
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn synthetic_five_second_stream_drains_without_underrun() {
        let queue = AudioQueue::default();
        let sample_count = AUDIO_SAMPLE_RATE as usize * AUDIO_CHANNELS as usize * 5;
        queue
            .push_samples((0..sample_count).map(|sample| (sample as f32 * 0.01).sin()))
            .unwrap();
        let mut output = vec![0.0; sample_count];
        assert_eq!(queue.drain_into(&mut output).unwrap(), sample_count);
        assert_eq!(queue.queued_samples().unwrap(), 0);
        assert!(output.iter().any(|sample| *sample != 0.0));
    }
}

