pub const PAIRING_IDENTITY_PREFIX: &str = "erd-p1.";
pub const PSK_CIPHER_LIST: &str = "PSK-AES128-GCM-SHA256:PSK-AES256-GCM-SHA384";
pub const MAX_PAIRING_ATTEMPTS: usize = 5;
