            if count == 0 {
                return Err(TlsPskError::Io(io::Error::new(
                    io::ErrorKind::UnexpectedEof,
                    "TLS stream closed while reading frame",
                )));
            }
            self.pending_events
                .extend(self.frame_reader.push(&buffer[..count]));
        }
    }
}

